CREATE OR REPLACE FUNCTION public.complete_staff_notification_push_delivery(p_delivery_id uuid, p_claimed_until timestamp with time zone, p_status text, p_error_code text DEFAULT NULL::text, p_revoke_subscription boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_updated boolean;
begin
  if p_status is null or p_status not in ('sent', 'failed', 'suppressed') then
    return false;
  end if;
  if p_status = 'suppressed' and p_error_code is distinct from 'stale_hold' then
    return false;
  end if;

  update public.staff_notification_push_deliveries d
  set
    status = case when p_revoke_subscription then 'failed' else p_status end,
    attempt_count = case
      when p_status = 'suppressed' then d.attempt_count
      else least(d.attempt_count + 1, 5)
    end,
    next_attempt_at = case
      when p_status in ('sent', 'suppressed') or p_revoke_subscription or d.attempt_count + 1 >= 5 then null
      when d.attempt_count + 1 = 1 then now() + interval '1 minute'
      when d.attempt_count + 1 = 2 then now() + interval '5 minutes'
      when d.attempt_count + 1 = 3 then now() + interval '15 minutes'
      else now() + interval '1 hour'
    end,
    claimed_until = null,
    error_code = left(p_error_code, 100),
    updated_at = now()
  where d.id = p_delivery_id
    and d.status = 'claimed'
    and d.claimed_until = p_claimed_until
  returning true into v_updated;

  if not found then
    return false;
  end if;

  if p_revoke_subscription then
    update public.staff_notification_push_subscriptions sub
    set revoked_at = coalesce(sub.revoked_at, now())
    where sub.id = (
      select d.subscription_id
      from public.staff_notification_push_deliveries d
      where d.id = p_delivery_id
    );
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.staff_notification_fresh_pick_hold_reminder_is_current(p_payload jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_stock_id uuid;
  v_held_by uuid;
  v_held_until timestamptz;
  v_held_at timestamptz;
  v_stock public.extra_stock;
begin
  if jsonb_typeof(p_payload) is distinct from 'object'
    or coalesce(p_payload ->> 'extra_stock_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or coalesce(p_payload ->> 'walk_in_held_by', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or nullif(p_payload ->> 'walk_in_held_at', '') is null
    or nullif(p_payload ->> 'walk_in_held_until', '') is null
  then
    return false;
  end if;

  v_stock_id := (p_payload ->> 'extra_stock_id')::uuid;
  v_held_by := (p_payload ->> 'walk_in_held_by')::uuid;
  begin
    v_held_at := (p_payload ->> 'walk_in_held_at')::timestamptz;
    v_held_until := (p_payload ->> 'walk_in_held_until')::timestamptz;
  exception
    when invalid_datetime_format or datetime_field_overflow then
      return false;
  end;

  select e.*
    into v_stock
  from public.extra_stock e
  where e.id = v_stock_id
  for update;

  if not found then
    return false;
  end if;

  return v_stock.lifecycle = 'confirmed'
    and v_stock.sold_at is null
    and v_stock.cut_into_slices_at is null
    and v_stock.walk_in_held_by = v_held_by
    and v_stock.walk_in_held_at = v_held_at
    and v_stock.walk_in_held_until = v_held_until
    and public.extra_walk_in_hold_is_active(
      v_stock.walk_in_held_until,
      clock_timestamp()
    );
end;
$function$

